import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.DCVnL8g5.js";const h=JSON.parse('{"title":"Introducción y casos de uso","description":"","frontmatter":{},"headers":[],"relativePath":"full-stack/frontend/zustand/01-introduccion-y-casos-de-uso.md","filePath":"full-stack/frontend/zustand/01-introduccion-y-casos-de-uso.md","lastUpdated":1789040978000,"isDraft":false}'),n={name:"full-stack/frontend/zustand/01-introduccion-y-casos-de-uso.md"};function r(i,e,c,d,l,u){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="introduccion-y-casos-de-uso" tabindex="-1">Introducción y casos de uso <a class="header-anchor" href="#introduccion-y-casos-de-uso" aria-label="Permalink to &quot;Introducción y casos de uso&quot;">​</a></h1><p>Zustand es un store <strong>pequeño y poco opinionado</strong>: estado + acciones en un objeto, consumido con un <strong>hook</strong>. No intenta ser Redux sin boilerplate. El modelo es más corto: <code>set</code> actualiza, el selector decide quién se renderiza.</p><p>Documentación: <a href="https://zustand.docs.pmnd.rs/" target="_blank" rel="noreferrer">Zustand</a>, <a href="https://zustand.docs.pmnd.rs/reference/apis/create" target="_blank" rel="noreferrer">create</a>, <a href="https://zustand.docs.pmnd.rs/learn/guides/beginner-typescript" target="_blank" rel="noreferrer">TypeScript</a>, <a href="https://github.com/pmndrs/zustand" target="_blank" rel="noreferrer">repo pmndrs/zustand</a>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>store</span></span>
<span class="line"><span>├── state     (líneas del carrito, filtro, tema)</span></span>
<span class="line"><span>└── actions   (anadirLinea, resetFiltros)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>componente → action → set(...) → store cambia → selector afectado → render</span></span></code></pre></div><p>En el caso <strong>global básico</strong> no hace falta <code>&lt;Provider&gt;</code>. El hook que devuelve <code>create</code> lee el módulo. Eso no es una ley: hay stores <strong>por instancia</strong> (capítulo 6).</p><h2 id="client-state-no-cache-http" tabindex="-1">Client state, no caché HTTP <a class="header-anchor" href="#client-state-no-cache-http" aria-label="Permalink to &quot;Client state, no caché HTTP&quot;">​</a></h2><p>Zustand brilla en <strong>estado cliente</strong>: sidebar, draft, filtros, wizard, ítem seleccionado, preferencias, carrito coordinado entre header y página.</p><p>No lo uses como receta principal de:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fetch → store → loading → caché → staleTime → invalidar a mano</span></span></code></pre></div><p>Eso es trabajo de una librería de <strong>server state</strong> (TanStack Query, RTK Query, etc.). Una app seria suele combinar <strong>ambas</strong>: Query cachea <code>/productos</code>; Zustand guarda el carrito y el filtro de la UI.</p><h2 id="cuando-si-cuando-no" tabindex="-1">Cuándo sí / cuándo no <a class="header-anchor" href="#cuando-si-cuando-no" aria-label="Permalink to &quot;Cuándo sí / cuándo no&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Herramienta</th><th>Encaja</th></tr></thead><tbody><tr><td><strong>useState</strong></td><td>Un input, un modal de un solo componente.</td></tr><tr><td><strong>Context</strong></td><td>Tema ya resuelto, “quién soy”, config que casi no cambia.</td></tr><tr><td><strong>Zustand</strong></td><td>Estado cliente compartido con updates y selectores sin Provider obligatorio.</td></tr><tr><td><strong>Redux Toolkit</strong></td><td>Convenciones, DevTools/tooling, RTK Query, un equipo que quiere ese flujo.</td></tr></tbody></table><p>Ni “Zustand siempre gana a Redux” ni lo contrario. Menos líneas no es mejor arquitectura. El <a href="./../redux/01-introduccion-y-casos-de-uso">manual Redux</a> cubre RTK; aquí el mismo carrito se resuelve con un store de 30 líneas <strong>si</strong> el problema es solo cliente.</p><p>No hace falta Zustand para tres <code>useState</code> en una ficha. Tampoco para sustituir la caché del backend.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Un <code>useAppStore</code> con productos, auth, formularios y caché HTTP.</li><li>Comparar solo el recuento de dependencias con RTK.</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>Empieza por el estado que <strong>varias</strong> pantallas deben ver igual.</li><li>Acciones junto al estado (capítulo 2); selectores pequeños (capítulo 3).</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Lista tres estados de tu app: local / cliente compartido / servidor.</li><li>Elige uno que merezca Zustand y uno que no.</li><li>Lee la intro oficial y anota que <code>create</code> ya es un hook.</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continúa con <a href="./02-stores-basicos">Stores básicos</a>.</p>`,22)])])}const g=a(n,[["render",r]]);export{h as __pageData,g as default};
